```python
prod_rows = sql_data.get('q_secondarypackaging_gross_018', [])
scrap_rows = sql_data.get('q_secondarypackaging_defects_018', [])
prods = {}
for p in prod_rows:
    uid = p.get('unit_id')
    if uid != None:
        prods[uid] = prods.get(uid, 0) + (p.get('total_qty', 0) or 0)
scraps = {}
for s in scrap_rows:
    uid = s.get('unit_id')
    if uid != None:
        scraps[uid] = scraps.get(uid, 0) + (s.get('reject_qty', 0) or 0)
for uid, total_p in prods.items():
    total_s = scraps.get(uid, 0)
    net = total_p - total_s
    out('net_production').append({'unit_id': uid, 'net_qty': net, 'produced': total_p, 'rejected': total_s})
```

```python
target_rows = sql_data.get('q_intralogisticsagv_gross_019', [])
actual_rows = sql_data.get('q_intralogisticsagv_defects_019', [])
targets = {}
for t in target_rows:
    lc = t.get('line_code')
    if lc != None:
        targets[lc] = targets.get(lc, 0) + (t.get('target_val', 0) or 0)
actuals = {}
for a in actual_rows:
    lc = a.get('line_code')
    if lc != None:
        actuals[lc] = actuals.get(lc, 0) + (a.get('actual_val', 0) or 0)
lines = []
for lc in targets:
    if lc not in lines:
        lines.append(lc)
for lc in actuals:
    if lc not in lines:
        lines.append(lc)
for lc in lines:
    tgt = targets.get(lc, 0)
    act = actuals.get(lc, 0)
    out('comparison').append({'line_code': lc, 'diff': act - tgt, 'actual': act, 'target': tgt})
```

